<script setup>
import { computed, onMounted, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const plugins=ref([]),types=ref([]),type=ref(''),selected=ref(null),config=ref('{}'),loading=ref(false),error=ref(''),notice=ref(''),file=ref(null),uploading=ref(false)
const shown=computed(()=>plugins.value.filter(p=>!type.value||p.type===type.value))
async function load(){loading.value=true;error.value='';try{const [t,p]=await Promise.all([props.api('plugin/types'),props.api(`plugin/getPlugins${type.value?'?type='+encodeURIComponent(type.value):''}`)]);types.value=t||[];plugins.value=p||[];if(selected.value)selected.value=plugins.value.find(p=>p.code===selected.value.code)||null;if(!selected.value&&plugins.value.length)selected.value=plugins.value[0];if(selected.value)await loadConfig()}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadConfig(){if(!selected.value)return;try{const d=await props.api(`plugin/config?code=${encodeURIComponent(selected.value.code)}`);config.value=JSON.stringify(d??{},null,2)}catch(e){error.value=e.message}}
async function action(act){const p=selected.value;if(!p)return;const labels={install:'安装',uninstall:'卸载',enable:'启用',disable:'停用',upgrade:'升级',delete:'删除'};if(['uninstall','upgrade','delete','disable'].includes(act)&&!window.confirm(`确认${labels[act]}插件 ${p.name}（${p.code}）？`))return;try{await props.api(`plugin/${act}`,{method:'POST',body:{code:p.code}});notice.value=`${labels[act]}操作已完成。`;await load()}catch(e){error.value=e.message}}
async function saveConfig(){try{const value=JSON.parse(config.value);await props.api('plugin/config',{method:'POST',body:{code:selected.value.code,config:value}});notice.value='插件配置已保存。'}catch(e){error.value=e instanceof SyntaxError?'插件配置不是有效 JSON。':e.message}}
async function upload(){if(!file.value)return;uploading.value=true;try{const data=new FormData();data.append('file',file.value);await props.api('plugin/upload',{method:'POST',body:data});file.value=null;notice.value='插件包已上传。';await load()}catch(e){error.value=e.message}finally{uploading.value=false}}
onMounted(load)
</script>
<template><section class="plugin-view"><div class="page-title-row"><div><p class="eyebrow">EXTENSIONS / PLUGINS</p><h1>插件<span class="title-period">.</span></h1><p class="page-subtitle">管理插件安装、启停、升级、配置和删除；核心插件受后端保护。</p></div><button class="refresh-button" @click="load">↻ <span>刷新列表</span></button></div><div class="plugin-upload data-panel"><div><p class="eyebrow">INSTALL / ZIP</p><h2>上传插件包</h2><p>仅支持 ZIP，最大 10 MB。</p></div><input type="file" accept=".zip,application/zip" @change="file=$event.target.files?.[0]||null"><button :disabled="uploading||!file" @click="upload">{{uploading?'上传中…':'上传 ZIP'}}</button></div><p v-if="error" class="notice">{{error}}</p><p v-if="notice" class="notice success">{{notice}}</p><div class="system-tabs plugin-filters"><button :class="{selected:!type}" @click="type='';load()">全部</button><button v-for="t in types" :key="t.value" :class="{selected:type===t.value}" @click="type=t.value;load()">{{t.icon}} {{t.label}}</button></div><div class="plugin-layout"><div class="data-panel plugin-list"><button v-for="p in shown" :key="p.code" :class="{selected:selected?.code===p.code}" @click="selected=p;loadConfig()"><span><b>{{p.name}}</b><small>{{p.code}} · v{{p.version}}</small><small>{{p.description}}</small></span><i :class="{enabled:p.is_enabled}">{{p.is_enabled?'已启用':p.is_installed?'已停用':'未安装'}}</i></button><div v-if="!shown.length&&!loading" class="table-state">没有匹配的插件。</div></div><article class="data-panel plugin-detail" v-if="selected"><div class="panel-heading"><div><p class="eyebrow">{{selected.code.toUpperCase()}} / PLUGIN</p><h2>{{selected.name}}</h2></div><span class="status-label">{{selected.author||selected.type}} · {{selected.version}}</span></div><p class="plugin-description">{{selected.description}}</p><div class="plugin-actions"><button v-if="!selected.is_installed" class="save-button" @click="action('install')">安装</button><button v-if="selected.is_installed&&!selected.is_enabled" class="save-button" @click="action('enable')">启用</button><button v-if="selected.is_enabled" @click="action('disable')">停用</button><button v-if="selected.is_installed" :disabled="!selected.need_upgrade" @click="action('upgrade')">{{selected.need_upgrade?'升级':'无需升级'}}</button><button v-if="selected.is_installed" class="danger-action" @click="action('uninstall')">卸载</button><button v-if="selected.can_be_deleted" class="danger-action" @click="action('delete')">删除文件</button></div><label class="plugin-config"><span>插件配置（JSON）</span><textarea v-model="config" rows="12" spellcheck="false" :disabled="!selected.is_installed"></textarea><button :disabled="!selected.is_installed" @click="saveConfig">保存配置</button></label><details v-if="selected.readme"><summary>插件说明</summary><pre>{{selected.readme}}</pre></details></article><article v-else class="data-panel table-state">选择插件查看详情。</article></div></section></template>
